// ───── مولّدات (أسئلة لا نهائية لا تتكرر) ─────
const R = (a, b) => a + Math.floor(Math.random() * (b - a + 1));
const pick = arr => arr[R(0, arr.length - 1)];

function numOpts(ans) {
  const s = new Set([ans]);
  const step = Math.max(1, Math.round(Math.abs(ans) * 0.1));
  for (let k = 1; s.size < 4 && k < 50; k++) s.add(ans + pick([-1, 1]) * step * R(1, 3));
  return [...s].map(String);
}

// رياضيات حسب الصف والمستوى: كل قالب يرجع [السؤال, الإجابة]
function mathQ(g, lvl) {
  const m = lvl; let q, a, opts;
  switch (g) {
    case 1: { const x = R(1, 5 * m + 4), y = R(1, x); [q, a] = pick([[`${x} + ${y} = ؟`, x + y], [`${x} − ${y} = ؟`, x - y]]); break; }
    case 2: { const x = R(10, 30 * m), y = R(1, x); [q, a] = pick([[`${x} + ${y} = ؟`, x + y], [`${x} − ${y} = ؟`, x - y], [`كم عشرة في ${R(2, 9) * 10}؟`, null]]);
      if (a === null) { const t = +q.match(/\d+/)[0]; a = t / 10; } break; }
    case 3: { const x = R(2, 3 + 2 * m), y = R(2, 10); [q, a] = pick([[`${x} × ${y} = ؟`, x * y], [`${R(100, 300 * m)} + ${R(10, 99)} = ؟`, null]]);
      if (a === null) { const [p1, p2] = q.match(/\d+/g).map(Number); a = p1 + p2; } break; }
    case 4: { const y = R(2, 9), k = R(2, 5 * m + 5); [q, a] = pick([[`${k * y} ÷ ${y} = ؟`, k], [`${R(11, 20 * m + 10)} × ${y} = ؟`, null]]);
      if (a === null) { const [p1, p2] = q.match(/\d+/g).map(Number); a = p1 * p2; } break; }
    case 5: { const d = R(3, 9), n1 = R(1, d - 2), n2 = R(1, d - n1 - 1);
      const t = pick(['frac', 'dec', 'per']);
      if (t === 'frac') { q = `${n1}/${d} + ${n2}/${d} = ؟`; a = `${n1 + n2}/${d}`; opts = [a, `${n1 + n2}/${2 * d}`, `${n1 + n2 + 1}/${d}`, `${Math.abs(n1 - n2)}/${d}`]; }
      else if (t === 'dec') { const x = R(1, 9 * m) + R(1, 9) / 10, y = R(1, 9) + R(1, 9) / 10; q = `${x.toFixed(1)} + ${y.toFixed(1)} = ؟`; a = (x + y).toFixed(1); opts = [a, (x + y + 1).toFixed(1), (x + y - 0.1).toFixed(1), (x + y + 0.2).toFixed(1)]; }
      else { const w = R(2, 5 * m + 3), h = R(2, 9); q = `مستطيل طوله ${w} سم وعرضه ${h} سم. ما محيطه؟`; a = 2 * (w + h); } break; }
    case 6: { const t = pick(['pct', 'ops', 'area']);
      if (t === 'pct') { const p = pick([10, 25, 50, 20]), n = R(2, 10 * m) * 20; q = `كم يساوي ${p}% من ${n}؟`; a = n * p / 100; }
      else if (t === 'ops') { const x = R(2, 9), y = R(2, 9), z = R(2, 5 * m); q = `${x} + ${y} × ${z} = ؟`; a = x + y * z; opts = [...new Set([a, (x + y) * z, a + 1, a - 2, a + 3])].slice(0, 4).map(String); }
      else { const b = R(2, 6 * m) * 2, h = R(2, 10); q = `مثلث قاعدته ${b} سم وارتفاعه ${h} سم. ما مساحته بالسنتيمتر المربع؟`; a = b * h / 2; } break; }
    case 7: { const t = pick(['int', 'eq1', 'eq2']);
      if (t === 'int') { const x = R(2, 15 * m), y = R(1, 20); q = `(−${x}) + ${y} = ؟`; a = y - x; }
      else if (t === 'eq1') { const x = R(1, 20 * m), k = R(2, 15); q = `إذا كان س + ${k} = ${x + k}، فما قيمة س؟`; a = x; }
      else { const x = R(2, 6 * m), k = R(2, 9); q = `إذا كان ${k}س = ${k * x}، فما قيمة س؟`; a = x; } break; }
    case 8: { const t = pick(['lin', 'pow']);
      if (t === 'lin') { const x = R(1, 5 * m + 3), k = R(2, 9), b = R(1, 20); q = `حُلّ المعادلة: ${k}س + ${b} = ${k * x + b}`; a = x; }
      else { const base = pick([2, 3, 5]), e = R(2, 2 + m); q = `${base} أُس ${e} = ؟`; a = base ** e; } break; }
    case 9: { const t = pick(['sq', 'ratio', 'neg']);
      if (t === 'sq') { const r = R(4, 8 * m + 6); q = `ما الجذر التربيعي للعدد ${r * r}؟`; a = r; }
      else if (t === 'ratio') { const p1 = R(1, 4), p2 = R(1, 5), u = R(2, 10 * m); q = `قُسّم مبلغ ${(p1 + p2) * u} ريالًا بين أخوين بنسبة ${p1} : ${p2}. كم نصيب الأول؟`; a = p1 * u; }
      else { const x = R(1, 9 * m), k = R(2, 6), b = R(1, 30); q = `حُلّ: ${k}س − ${b} = ${k * x - b}`; a = x; } break; }
    case 10: { const t = pick(['root', 'slope', 'inc']);
      if (t === 'root') { const r = R(2, 6 * m + 4); q = `ما القيمة الموجبة لـ س إذا كان س² = ${r * r}؟`; a = r; }
      else if (t === 'slope') { const k = R(1, 4 * m), x1 = R(0, 5), y1 = R(0, 5), dx = R(1, 4); q = `ما ميل المستقيم المار بالنقطتين (${x1}، ${y1}) و(${x1 + dx}، ${y1 + k * dx})؟`; a = k; }
      else { const p = pick([10, 20, 25, 50]), n = R(1, 10 * m) * 20; q = `زاد سعر سلعة من ${n} ريالًا بنسبة ${p}%. كم أصبح السعر؟`; a = n + n * p / 100; } break; }
    case 11: { const t = pick(['nth', 'log', 'sum']);
      if (t === 'nth') { const a1 = R(1, 10), d = R(2, 3 * m + 2), n = R(5, 10 * m); q = `متتالية حسابية حدها الأول ${a1} وأساسها ${d}. ما الحد رقم ${n}؟`; a = a1 + (n - 1) * d; }
      else if (t === 'log') { const e = R(2, 4 + 2 * m); q = `ما قيمة لو₂(${2 ** e})؟`; a = e; }
      else { const n = R(5, 10 * m + 5); q = `ما مجموع الأعداد الطبيعية من 1 إلى ${n}؟`; a = n * (n + 1) / 2; } break; }
    default: { const t = pick(['der', 'roots', 'log10']);
      if (t === 'der') { const c = R(1, 3 * m), n = R(2, 3 + m), x = R(1, 3); q = `إذا كان ص = ${c}س^${n}، فما قيمة المشتقة عند س = ${x}؟`; a = c * n * x ** (n - 1); }
      else if (t === 'roots') { const r1 = R(1, 6 * m), r2 = R(1, 9); q = `ما مجموع جذري المعادلة: س² − ${r1 + r2}س + ${r1 * r2} = 0؟`; a = r1 + r2; }
      else { const e = R(2, 2 + 2 * m); q = `ما قيمة لو(${'1' + '0'.repeat(e)})؟`; a = e; } }
  }
  return { id: 'm' + Math.random().toString(36).slice(2), cat: 'math', q, opts: opts || numOpts(a), a: 0, gen: true };
}

// سلاسل منطقية لتمرين المخ: الصعوبة تزيد مع الصف والمستوى
function iqQ(g, lvl) {
  const tier = Math.min(4, Math.floor((g - 1) / 3) + Math.max(0, lvl - 2));
  const kinds = ['add', 'add', 'mul', 'alt', 'sq', 'fib', 'tri'].slice(0, 2 + tier * 1.25 | 0);
  const k = pick(kinds); let s;
  if (k === 'add') { const a = R(1, 10), d = R(1, 3 + g); s = [0, 1, 2, 3, 4].map(i => a + i * d); }
  else if (k === 'mul') { const a = R(1, 4), r = pick([2, 3]); s = [0, 1, 2, 3, 4].map(i => a * r ** i); }
  else if (k === 'alt') { const a = R(10, 30), u = R(3, 9), v = R(1, u - 1); s = [a]; for (let i = 1; i < 5; i++) s.push(s[i - 1] + (i % 2 ? u : -v)); }
  else if (k === 'sq') { const o = R(1, 5); s = [0, 1, 2, 3, 4].map(i => (o + i) ** 2); }
  else if (k === 'fib') { s = [R(1, 4), R(2, 6)]; while (s.length < 5) s.push(s.at(-1) + s.at(-2)); }
  else { s = [R(1, 5)]; for (let i = 1; i < 5; i++) s.push(s[i - 1] + 2 * i); } // الفروق 2، 4، 6، 8
  const ans = s.pop();
  return { id: 'i' + Math.random().toString(36).slice(2), cat: 'iq', q: `أكمل السلسلة: ${s.join('، ')}، ؟`, opts: numOpts(ans), a: 0, gen: true };
}

